import { can, PermissionDeniedError } from "@/lib/permissions";
import { createLogger } from "@/lib/logger";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringIssueRepo from "@/server/repositories/recurring-issue-repository";
import { createIssue } from "@/server/services/issue-service";
import { runJob } from "./types";
import type { JobResult } from "./types";
import type { RecurringIssue } from "@/types/recurring-issue";
import type { Actor } from "@/types/member";
import { projectResource } from "@/server/services/_support";

const logger = createLogger("recurring-issue-job");

export async function runRecurringIssueJob(now: Date): Promise<JobResult> {
  return runJob("recurring-issues", async (result) => {
    const rules = await recurringIssueRepo.listRunnableRecurringIssues();

    for (const rule of rules) {
      try {
        const occurrenceOn = latestStartedOccurrence(rule, now);
        if (
          occurrenceOn === null ||
          (rule.lastOccurrenceOn !== null &&
            occurrenceOn <= rule.lastOccurrenceOn)
        ) {
          continue;
        }

        const project = await projectRepo.findProjectById(
          rule.orgId,
          rule.projectId,
        );
        if (!project || project.archivedAt !== null) continue;

        const creatorMember = await memberRepo.findMember(
          rule.orgId,
          rule.createdBy,
        );
        if (!creatorMember || creatorMember.status !== "active") {
          await recurringIssueRepo.setRecurringIssuePaused(
            rule.orgId,
            rule.id,
            true,
          );
          continue;
        }

        const actor: Actor = {
          userId: rule.createdBy,
          orgId: rule.orgId,
          role: creatorMember.role,
        };
        if (!can(actor, "issue:create", projectResource(project))) {
          await recurringIssueRepo.setRecurringIssuePaused(
            rule.orgId,
            rule.id,
            true,
          );
          continue;
        }

        const assigneeMember =
          rule.assigneeId === null
            ? null
            : await memberRepo.findMember(rule.orgId, rule.assigneeId);
        const assigneeId =
          assigneeMember?.status === "active" ? rule.assigneeId : null;

        try {
          await createIssue(actor, {
            orgId: rule.orgId,
            projectId: rule.projectId,
            title: `${rule.title} (${occurrenceOn})`,
            description: null,
            status: "backlog",
            priority: rule.priority,
            assigneeId,
            parentId: null,
            estimate: null,
            dueAt: null,
            labelIds: [],
          });
        } catch (error) {
          if (
            error instanceof PermissionDeniedError &&
            error.action === "issue:create"
          ) {
            await recurringIssueRepo.setRecurringIssuePaused(
              rule.orgId,
              rule.id,
              true,
            );
            continue;
          }
          throw error;
        }

        result.processed += 1;
        await recurringIssueRepo.setRecurringIssueLastOccurrenceOn(
          rule.orgId,
          rule.id,
          occurrenceOn,
        );
      } catch (error) {
        result.failed += 1;
        logger.error("recurring issue rule failed", {
          recurringIssueId: rule.id,
          orgId: rule.orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

function latestStartedOccurrence(
  rule: RecurringIssue,
  now: Date,
): string | null {
  const localDate = dateInTimeZone(now, rule.timezone);
  if (rule.cadence === "daily") {
    return localDate >= rule.startsOn ? localDate : null;
  }

  if (rule.weekday === null) return null;
  const currentWeekday = isoWeekday(localDate);
  const daysBack = (currentWeekday - rule.weekday + 7) % 7;
  const occurrence = shiftDate(localDate, -daysBack);
  return occurrence >= rule.startsOn ? occurrence : null;
}

function dateInTimeZone(now: Date, timezone: string): string {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone: timezone,
    calendar: "iso8601",
    numberingSystem: "latn",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(now);
  const values = new Map(parts.map(({ type, value }) => [type, value]));
  return `${values.get("year")!.padStart(4, "0")}-${values.get("month")}-${values.get("day")}`;
}

function isoWeekday(date: string): number {
  const [year, month, day] = date.split("-").map(Number);
  const weekday = new Date(Date.UTC(year, month - 1, day)).getUTCDay();
  return weekday === 0 ? 7 : weekday;
}

function shiftDate(date: string, amount: number): string {
  const [year, month, day] = date.split("-").map(Number);
  const shifted = new Date(Date.UTC(year, month - 1, day + amount));
  return [
    String(shifted.getUTCFullYear()).padStart(4, "0"),
    String(shifted.getUTCMonth() + 1).padStart(2, "0"),
    String(shifted.getUTCDate()).padStart(2, "0"),
  ].join("-");
}

