      assigneeId: input.assigneeId,
      cadence: input.cadence,
      weekday: input.weekday,
      timezone: input.timezone,
      startsOn: input.startsOn,
      lastOccurrenceOn: null,
      paused: false,
      createdBy,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();
  return toRecurringIssue(row);
}

export async function findRecurringIssueById(
  orgId: OrgId,
  recurringIssueId: string,
): Promise<RecurringIssue | null> {
  const row = getDb()
    .select()
    .from(recurringIssues)
    .where(
      and(
        orgPredicate(recurringIssues.orgId, orgId),
        eq(recurringIssues.id, recurringIssueId),
      ),
    )
    .get();
  return row ? toRecurringIssue(row) : null;
}

/** Tenant scoped rules, oldest first for stable creation-order listing. */
export async function listRecurringIssues(
  orgId: OrgId,
): Promise<readonly RecurringIssue[]> {
  const rows = getDb()
    .select()
    .from(recurringIssues)
    .where(orgPredicate(recurringIssues.orgId, orgId))
    .orderBy(asc(recurringIssues.createdAt), asc(recurringIssues.id))
    .all();
  return rows.map(toRecurringIssue);
}

/** All runnable rules are read only by the recurring issue job. */
export async function listRunnableRecurringIssues(): Promise<readonly RecurringIssue[]> {
  const rows = getDb()
    .select()
    .from(recurringIssues)
    .where(eq(recurringIssues.paused, false))
    .orderBy(asc(recurringIssues.createdAt), asc(recurringIssues.id))
    .all();
  return rows.map(toRecurringIssue);
}

export async function setRecurringIssuePaused(
  orgId: OrgId,
  recurringIssueId: string,
  paused: boolean,
): Promise<RecurringIssue> {
  return updateRecurringIssue(orgId, recurringIssueId, { paused });
}

export async function setRecurringIssueLastOccurrenceOn(
  orgId: OrgId,
  recurringIssueId: string,
  lastOccurrenceOn: string,
): Promise<RecurringIssue> {
  return updateRecurringIssue(orgId, recurringIssueId, { lastOccurrenceOn });
}

async function updateRecurringIssue(
  orgId: OrgId,
  recurringIssueId: string,
  patch: { paused?: boolean; lastOccurrenceOn?: string },
): Promise<RecurringIssue> {
  const row = getDb()
    .update(recurringIssues)
    .set({ ...patch, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(
        orgPredicate(recurringIssues.orgId, orgId),
        eq(recurringIssues.id, recurringIssueId),
      ),
    )
    .returning()
    .get();
  if (!row) throw new Error(`Recurring issue ${recurringIssueId} not found`);
  return toRecurringIssue(row);
}

